 Tính $\widehat{ADB}$ biết $\widehat{B}-\widehat{C}=144^{\circ}  $.  
\loigiai{
\begin{tikzpicture}
    % Points
    \coordinate [label=above:$A$] (A) at (0,3);
    \coordinate [label=below left:$B$] (B) at (-2,0);
    \coordinate [label=below:$D$] (D) at (0,0);
    \coordinate [label=below right:$C$] (C) at (3,0);

    % Triangle sides
    \draw [thick] (B) -- (A) -- (C) -- cycle;

    % Altitude
    \draw [thick] (A) -- (D);

    % Angles
    \draw [thick] (B) -- (A) -- (D);
    \draw [thick] (C) -- (A) -- (D);

    % Angle marks

    \node at (-0.1,2.6) {$1$};
    \node at (0.2,2.6) {$2$};

    % Points
    \filldraw [black] (A) circle (1.5pt);
    \filldraw [black] (B) circle (1.5pt);
    \filldraw [black] (C) circle (1.5pt);
    \filldraw [black] (D) circle (1.5pt);
\end{tikzpicture}
Ta có $\widehat{BAC}=180^{\circ} -\widehat{B}-\widehat{C}$\\
Vì ${AD}$ là tia phân giác của $\widehat{A}$ nên $\widehat{A_{1}}=\widehat{A_{2}}= \dfrac{1}{2} \widehat{A} = \dfrac{1}{2} (180^{\circ} -\widehat{B}-\widehat{C})=90^{\circ} -\dfrac{1}{2}\widehat{B}-\dfrac{1}{2}\widehat{C} $\\
Ta lại có $\widehat{A_{1}}+\widehat{B} + \widehat{ADB}=180^{\circ}$\\
suy ra $\widehat{ADB}= 180^{\circ}-\widehat{A_{1}}-\widehat{B}= 180^{\circ}-\left( 90^{\circ} -\dfrac{1}{2}\widehat{B}-\dfrac{1}{2}\widehat{C} \right)-\widehat{B}= 90^{\circ} -\dfrac{1}{2} (\widehat{B}-\widehat{C})=18^{\circ}$
}\end{ex}

